  }
  .topbar .search input {
    font-size: 12px;
  }
  .top-actions {
    gap: 8px;
  }
  .top-actions > .avatar {
    display: none;
  }
  main {
    padding: 24px 18px;
  }
  h1 {
    font-size: 25px;
  }
  .page-head {
    margin-bottom: 20px;
    align-items: flex-start;
  }
  .page-head .date {
    display: none;
  }
  .sub {
    font-size: 12px;
  }
  .hero {
    padding: 25px;
    min-height: 210px;
  }
  .hero h2 {
    font-size: 26px;
  }
  .hero p {
    font-size: 11px;
  }
  .hero-compass {
    display: none;
  }
  .panel {
    padding: 17px;
  }
  .layout,
  .stack {
    gap: 19px;
  }
  .section-bar h2 {
    font-size: 16px;
  }
  .week {
    gap: 5px;
  }
  .day-head {
    font-size: 9px;
    flex-direction: column;
    gap: 4px;
  }
  .day-head strong {
    font-size: 15px;
  }
  .calendar-item {
    padding: 7px 5px;
    min-height: 75px;
  }
  .calendar-item strong {
    font-size: 8px;
    overflow-wrap: anywhere;
  }
  .calendar-item span {
    font-size: 8px;
  }
  .add-day {
    font-size: 0;
  }
  .add-day .icon {
