  }
  .event-grid {
    grid-template-columns: 1fr 1fr;
    gap: 12px;
  }
  .event-grid .event-card:last-child:nth-child(3) {
    display: none;
  }
  .event-body {
    padding: 12px;
  }
  .poster {
    padding: 14px;
    height: 112px;
  }
  .poster b {
    font-size: 19px;
    max-width: 100px;
  }
  .event-title h3 {
    font-size: 12px;
  }
  .meta {
    font-size: 9px;
  }
  .reason {
    font-size: 9px;
  }
  .event-body .btn {
    font-size: 9px;
  }
  .rail {
    grid-template-columns: 1fr;
  }
  .rail .panel:nth-child(2) {
    display: none;
  }
  .planner-teaser {
    display: grid;
    grid-template-columns: 80px 1fr;
    column-gap: 15px;
    text-align: left;
    align-items: center;
  }
  .planner-teaser .mascot {
    grid-row: 1/5;
    margin: 0;
  }
  .planner-teaser h2 {
    font-size: 17px;
  }
  .planner-teaser p {
    margin: 5px 0 12px;
  }
  .planner-teaser .label {
    display: none;
  }
  .planner-layout > .stack {
    display: flex;
  }
  .chat-panel {
    min-height: 570px;
  }
  .bubble {
    max-width: 95%;
    font-size: 12px;
  }
  .messages {
    max-height: 450px;
  }
  .section-footer {
    display: block;
    font-size: 9px;
  }
  .section-footer span {
    display: block;
    margin-bottom: 7px;
  }
  .form-grid {
    grid-template-columns: 1fr;
  }
  .field.full {
    grid-column: auto;
  }
  .page-head .btn {
    font-size: 10px;
    padding: 8px;
  }
  .settings-row {
    align-items: flex-start;
  }
  .filters {
    gap: 6px;
  }
  .chip {
    font-size: 10px;
    padding: 7px 10px;
  }
  #toast {
    left: 50%;
    width: max-content;
  }
  .draft-item h3 {
    font-size: 13px;
  }
  .chat-header .label {
    display: none;
  }
}
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation: none !important;
    transition: none !important;
    scroll-behavior: auto !important;
  }
}

