}
.bubble {
  font-size: 13px;
}
.composer textarea {
  font-size: 13px;
}
.section-footer {
  font-size: 11px;
}
.legend {
  font-size: 11px;
}
@media (max-width: 700px) {
  .sidebar {
    visibility: hidden;
  }
  .sidebar.open {
    visibility: visible;
  }
  .chat-panel {
    height: 660px;
    min-height: 0;
  }
  .calendar-item strong {
    font-size: 10px;
  }
  .calendar-item span {
    font-size: 9px;
  }
  .event-grid {
    grid-template-columns: 1fr;
  }
  .event-grid .event-card:last-child:nth-child(3) {
    display: flex;
  }
  .poster {
    height: 130px;
  }
  .event-title h3 {
    min-height: 0;
    font-size: 16px;
  }
  .event-body {
    padding: 16px;
  }
  .event-body .btn {
    min-height: 40px;
    font-size: 12px;
  }
  .event-body .meta,
  .event-body .reason {
    font-size: 12px;
  }
  .meta .icon {
