      },
    },
    { message: "AI", state: schedulePayload(state), previous: { limit: 100 } },
    { message: "after 99 pm", state: schedulePayload(state) },
    ...[
      "before 11:99 am",
      "after 13 pm",
      "before 0 am",
      "before 11:9",
      "after 1:999",
      "after 999999999999999999999999999999",
    ].map((message) => ({ message, state: schedulePayload(state) })),
