        const latest = demo.read();
        if (
          event &&
          !latest.plan.includes(id) &&
          !matches.some((e) => e.id === id) &&
          !issue(event, {
            ...latest,
            plan: [...latest.plan, ...matches.map((e) => e.id)],
          })
        )
