    }
    // 2. Drop day constraint and retry
    if (constraints.days?.length) {
      const noDay = { ...constraints };
      delete noDay.days;
      const alt = recommend(snapshot, noDay, 4, true);
      if (alt.length) {
        const dayNames = constraints.days.map((d) => DAY_NAMES[d]).filter(Boolean).join("/");
