                    <button className="text-btn" onClick={() => nav("forum")}>
                      Join the conversation <Icon name="arrow" />
                    </button>
                  </section>
                </aside>
              </div>
            </>
          ) : null}
          {page === "explore" || page === "saved" ? (
            <>
              <Heading
                title={
