          {page === "notifications" ? (
            openNotification_ ? (
              <NotificationDetail
                notification={openNotification_}
                timeZone={campusZone}
                onBack={closeNote}
                onViewEvent={setDetail}
                onOpenCommunity={(id) => nav("forum", id)}
                onExplore={() => nav("explore")}
                onMarkUnread={() => {
