            ) : (
              <NotificationsPage
                list={notifications}
                readIds={state.readNotificationIds}
                timeZone={campusZone}
                filter={noteFilter}
                setFilter={setNoteFilter}
                onOpen={openNotification}
                onMarkAllRead={() => markRead(unreadNotes.map((n) => n.id))}
              />
            )
