    notify(
      `${batch!.label}: ${applied.length} update${applied.length > 1 ? "s" : ""} applied.${planNotice}${conflictNotice} See Briefing for details. · Synthetic update`,
      planned.length > 0
        ? [{ label: "View briefing", run: () => nav("dashboard") }]
        : [],
