}
.rail .panel {
  padding: 20px;
}
.rail h2 {
  font-size: 14px;
}
.planner-teaser {
  text-align: center;
  background: #fff;
}
.mascot {
  width: 125px;
  height: 120px;
  object-fit: contain;
