}
.planner-teaser h2 {
  font-size: 19px;
}
.planner-teaser p {
  font-size: 11px;
  color: var(--muted);
  margin: 9px 0 16px;
}
.planner-teaser .btn {
  width: 100%;
}
.label {
  font-size: 9px;
