}
.feed strong {
  font-size: 11px;
  font-weight: 600;
  line-height: 1.5;
}
.feed p {
  font-size: 10px;
  color: var(--muted);
  margin: 4px 0 0;
}
.feed .text-btn {
  font-size: 10px;
  margin-top: 6px;
  padding-left: 0;
}
.group {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 10px 0;
}
.group-icon {
  width: 32px;
  height: 32px;
  border-radius: 9px;
