    padding: 38px 45px;
  }
  .event-grid {
    gap: 20px;
  }
  .poster {
    height: 145px;
  }
  .event-title h3 {
    font-size: 15px;
  }
  .meta {
    font-size: 11px;
  }
  .hero {
    min-height: 230px;
  }
