}
.forum-create-body {
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
  padding: 12px;
  font-size: 14px;
  color: var(--ink);
  resize: vertical;
  min-height: 160px;
  outline: none;
  line-height: 1.6;
}
.forum-create-body:focus {
  border-color: var(--green);
  outline: 3px solid #57a77a33;
}
.forum-create-toolbar {
  display: flex;
  align-items: center;
  gap: 4px;
  border: 1px solid var(--line);
  border-radius: 8px;
  padding: 6px 10px;
  background: white;
  flex-wrap: wrap;
}
.forum-toolbar-group {
  display: flex;
  align-items: center;
  gap: 2px;
}
.forum-toolbar-group button {
  border: none;
  background: none;
  border-radius: 5px;
  padding: 4px 8px;
  font-size: 13px;
  color: var(--muted);
  cursor: pointer;
}
.forum-toolbar-group button:hover {
  background: var(--bg);
  color: var(--ink);
}
.forum-toolbar-sep {
  width: 1px;
  height: 18px;
  background: var(--line);
  margin: 0 4px;
  display: inline-block;
}
.forum-create-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
  padding-top: 8px;
}
/* First-visit welcome prompt: close (top right) applies default preferences */
.welcome-dialog {
  position: fixed;
  overflow: visible;
  padding-right: 56px;
}
.welcome-close {
  position: absolute;
  top: 12px;
  right: 12px;
}
/* ── Top bar: bordered search, quick links, sign in ─────────────────────── */
.topbar {
  justify-content: flex-start;
}
.topbar .search {
  flex: 0 1 420px;
  width: auto;
  height: 44px;
  padding: 0 4px 0 16px;
  border: 1px solid #d3dbd2;
  border-radius: 999px;
  background: var(--bg);
  transition:
    border-color 0.15s,
    background 0.15s;
}
.topbar .search:hover {
  border-color: #b9c6b8;
}
.topbar .search:focus-within {
  background: #fff;
  border-color: var(--green);
  outline: 3px solid #57a77a40;
  outline-offset: 0;
}
.search-go {
  flex: none;
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 50%;
  background: var(--green);
  color: #fff;
  display: grid;
  place-items: center;
  cursor: pointer;
}
.search-go:hover {
  background: var(--green-dark);
}
.search-go svg {
  width: 16px;
  height: 16px;
}
.top-links {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 4px;
}
.top-links button {
  border: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 13px;
  font-weight: 650;
  padding: 9px 12px;
  border-radius: 8px;
  white-space: nowrap;
  cursor: pointer;
}
.top-links button:hover {
  background: var(--mint);
}
.top-links button.active {
  color: var(--green);
  box-shadow: inset 0 -2px 0 var(--green);
  border-radius: 8px 8px 0 0;
}
.top-links .top-cta {
  margin-left: 6px;
  background: var(--green);
  color: #fff;
}
.top-links .top-cta:hover,
.top-links .top-cta.active {
  background: var(--green-dark);
  color: #fff;
  box-shadow: none;
  border-radius: 8px;
}
.topbar .top-actions {
  gap: 10px;
}
.sign-in {
  border: 0;
  background: transparent;
  color: var(--ink);
  font: inherit;
  font-size: 13px;
  font-weight: 650;
  padding: 9px 4px 9px 8px;
  white-space: nowrap;
  cursor: pointer;
}
.sign-in:hover {
  color: var(--green);
  text-decoration: underline;
  text-underline-offset: 4px;
}
.avatar.guest {
  background: var(--mint);
  color: var(--green);
}
.avatar.guest svg {
  width: 16px;
  height: 16px;
}
.signin-dialog form {
  margin-top: 12px;
}
@media (max-width: 1180px) {
  .top-links button:not(.top-cta) {
    padding: 9px 8px;
  }
}
@media (max-width: 1060px) {
  .top-links button:not(.top-cta) {
    display: none;
  }
}
@media (max-width: 700px) {
  .top-links {
    display: none;
  }
  .topbar .search {
    flex: 1;
    height: 40px;
  }
  .top-actions > .avatar {
    display: grid;
  }
  .top-actions .icon-btn {
    display: none;
  }
}

/* ── Synthetic update loop ───────────────────────────────────────────── */
:root {
  --conflict-bg: #fdf2f2;
  --conflict-ink: #922;
  --conflict-border: #f5c0c0;
  --updated-bg: #f0f8ff;
  --updated-ink: #1a4a7a;
  --updated-border: #b8d4f0;
}

.badge--conflict {
  display: inline-block;
  background: var(--conflict-bg);
  color: var(--conflict-ink);
  border: 1px solid var(--conflict-border);
  border-radius: 5px;
  font-size: 11px;
  padding: 1px 7px;
  font-weight: 600;
  vertical-align: middle;
}

.badge--updated {
  display: inline-block;
  background: var(--updated-bg);
  color: var(--updated-ink);
  border: 1px solid var(--updated-border);
  border-radius: 5px;
  font-size: 11px;
  padding: 1px 7px;
  font-weight: 500;
  vertical-align: middle;
}

.badge--planned {
  display: inline-block;
  background: var(--mint);
  color: var(--green);
  border-radius: 5px;
  font-size: 11px;
  padding: 1px 7px;
  font-weight: 500;
  vertical-align: middle;
}

.event-card--conflict {
  border-left: 3px solid var(--conflict-border);
}

.event-card--updated {
  border-left: 3px solid var(--updated-border);
}

.event-tag-row {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  margin-bottom: 4px;
}

.meta--fineprint {
  opacity: 0.75;
  font-size: 11px;
}

/* Update feed in Briefing / bell menu */
.update-feed {
  background: var(--updated-bg);
  border: 1px solid var(--updated-border);
  border-radius: var(--radius);
  padding: 14px 16px;
  margin-bottom: 16px;
}

.update-feed h3 {
  font-size: 13px;
  margin: 0 0 10px;
  display: flex;
  align-items: center;
  gap: 6px;
}

.update-list {
  list-style: none;
  padding: 0;
  margin: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.update-item {
  border-radius: 8px;
  background: white;
  padding: 9px 12px;
  display: flex;
  align-items: flex-start;
  flex-wrap: wrap;
  gap: 6px;
}

.update-item--planned {
  background: var(--mint);
}

.update-item--conflict {
  background: var(--conflict-bg);
  border: 1px solid var(--conflict-border);
}

.update-tag {
  font-size: 11px;
  border-radius: 4px;
  padding: 1px 7px;
}

.update-tag--cancelled {
  background: #fde8e8;
  color: #8b2020;
}

.update-tag--full {
  background: #fdf0e0;
  color: #7a4a10;
}

.update-tag--time_moved {
  background: #e8f0fd;
  color: #1a3c8b;
}

.update-tag--room_changed {
  background: #e8fdf0;
  color: #1a5c35;
}

.update-detail {
  width: 100%;
  margin: 4px 0 0;
  font-size: 12px;
  color: var(--muted);
  line-height: 1.5;
}

.notice--conflict {
  background: var(--conflict-bg);
  color: var(--conflict-ink);
  border: 1px solid var(--conflict-border);
}

.notice--updated {
  background: var(--updated-bg);
  color: var(--updated-ink);
  border: 1px solid var(--updated-border);
}

.item--conflict > .text-btn {
  color: var(--conflict-ink);
  font-weight: 600;
}

.item--updated > .text-btn {
  color: var(--updated-ink);
}

/* ═══════════════════════════════════════════════════════════════════════════
   Google-Calendar-style CalendarView (My Calendar page only)
   ═══════════════════════════════════════════════════════════════════════════ */

/* Root wrapper */
.gcal-root {
  display: flex;
  flex-direction: column;
  gap: 0;
  margin-bottom: 28px;
}

/* ── Toolbar ──────────────────────────────────────────────────────────────── */
/*
 * Fix #8: at ≥ 1024 px the toolbar-right uses a 2-row sub-layout so the
 * switcher always sits in the top row and doesn't jump when the title
 * changes length.  On smaller screens everything wraps as before.
 */
.gcal-toolbar {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  margin-bottom: 10px;
}
.gcal-toolbar-left {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-wrap: wrap;
  flex: 1;
  min-width: 0;
}
.gcal-toolbar-right {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 4px;
  flex: none;
}
.gcal-toolbar-right-top {
  display: flex;
  align-items: center;
  gap: 8px;
}
.gcal-toolbar-right-bottom {
  display: flex;
  align-items: center;
  gap: 8px;
}
.gcal-today-btn {
  font-size: 12px;
  flex: none;
}
.gcal-nav-btn {
  border: 1px solid var(--line);
  background: white;
  border-radius: 7px;
  width: 30px;
  height: 30px;
  font-size: 16px;
  display: inline-grid;
  place-items: center;
  line-height: 1;
  flex: none;
}
.gcal-nav-btn:hover {
  background: var(--mint);
}
.gcal-title {
  font-size: 15px;
  font-weight: 650;
  color: var(--ink);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

/* View switcher */
.gcal-view-switcher {
  display: flex;
  border: 1px solid var(--line);
  border-radius: 8px;
  overflow: hidden;
}
.gcal-switch-btn {
  background: white;
  border: 0;
  border-left: 1px solid var(--line);
  padding: 6px 11px;
  font-size: 12px;
  font-weight: 600;
  color: var(--muted);
}
.gcal-switch-btn:first-child {
  border-left: 0;
}
.gcal-switch-btn:hover {
  background: var(--bg);
  color: var(--ink);
}
.gcal-switch-btn.active,
.gcal-switch-btn[aria-pressed="true"] {
  background: var(--mint);
  color: var(--green);
}
.gcal-switch-btn:focus-visible {
  outline: 3px solid #57a77a;
  outline-offset: -2px;
  z-index: 1;
  position: relative;
}

/* Legend sits just below toolbar */
.gcal-legend {
  margin-bottom: 8px;
  margin-top: 0;
}

/* Demo banner */
.gcal-demo-banner {
  display: flex;
  align-items: center;
  gap: 12px;
  background: var(--notice-bg);
  color: var(--notice-ink);
  border-radius: 9px;
  padding: 10px 14px;
  font-size: 12px;
  margin-bottom: 10px;
  flex-wrap: wrap;
}

/* ── Body (panel) ─────────────────────────────────────────────────────────── */
.gcal-body {
  padding: 0;
  overflow: hidden;
}

/*
 * .gcal-scroll-host — horizontal scroll for phones (overflow-x: auto).
 *
 * The header and body are BOTH inside .gcal-time-grid-wrap (vertical scroll,
 * scrollbar-gutter: stable).  Because they share the same containing block
 * the scrollbar lane is counted identically for header and day columns, so
 * there is no drift at any desktop or phone width.
 */
.gcal-scroll-host {
  overflow-x: auto;
}

/*
 * Both .gcal-col-headers and .gcal-time-grid share --gcal-min-w so their
 * widths are always identical and can never drift apart again.
 */
:root {
  --gcal-min-w: 500px;
}

/* ── Column headers (Day/Week) ────────────────────────────────────────────── */
.gcal-col-headers {
  display: flex;
  border-bottom: 1px solid var(--line);
  background: white;
  position: sticky;
  top: 0;
  z-index: 5;
  min-width: var(--gcal-min-w);
}
.gcal-gutter {
  width: 56px;
  flex: none;
}
.gcal-col-head {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 6px 4px;
  gap: 2px;
  min-width: 0;
}
.gcal-dow {
  font-size: 10px;
  color: var(--muted);
  text-transform: uppercase;
  letter-spacing: 0.5px;
}
/*
 * Issue 2: give .gcal-dom a fixed height so the today-circle (32 px) does
 * not make Monday's column taller than the others — all "+" buttons stay on
 * one row.
 */
.gcal-dom {
  font-size: 20px;
  font-weight: 600;
  color: var(--ink);
  line-height: 1;
  min-width: 32px;
  height: 32px;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  text-align: center;
}
.gcal-today-head .gcal-dow {
  color: var(--green);
}
.gcal-today-dot {
  background: var(--green);
  color: white !important;
  border-radius: 999px;
  min-width: 32px;
  height: 32px;
  display: inline-grid;
  place-items: center;
}

/* Fix #4: "+" button in the column header */
.gcal-add-header-btn {
  border: 1px dashed #b5c9b2;
  background: none;
  color: var(--green);
  border-radius: 50%;
  width: 20px;
  height: 20px;
  display: inline-grid;
  place-items: center;
  margin-top: 2px;
  flex: none;
}
.gcal-add-header-btn .icon {
  width: 12px;
  height: 12px;
}
.gcal-add-header-btn:hover {
  background: var(--mint);
}
.gcal-add-header-btn:focus-visible {
  outline: 2px solid #57a77a;
  outline-offset: 2px;
}

/* ── Time grid ────────────────────────────────────────────────────────────── */
/*
 * .gcal-time-grid-wrap contains BOTH the sticky header and the day columns.
 * scrollbar-gutter:stable reserves the scrollbar lane for BOTH, so their
 * widths are always identical — no drift at any viewport width.
 * overflow-x is visible so .gcal-scroll-host handles horizontal scrolling.
 */
.gcal-time-grid-wrap {
  overflow-y: auto;
  overflow-x: visible;
  max-height: 580px;
  scrollbar-gutter: stable;
}
.gcal-time-grid {
  display: flex;
  position: relative;
  min-width: var(--gcal-min-w);
}
/* Gutter with hour labels */
.gcal-gutter {
  display: flex;
  flex-direction: column;
  width: 56px;
  flex: none;
  border-right: 1px solid var(--line);
  background: white;
  position: sticky;
  left: 0;
  z-index: 4;
}
.gcal-hour-label {
  font-size: 9px;
  color: var(--muted);
  padding: 0 6px;
  text-align: right;
  height: 48px;
  display: flex;
  align-items: flex-start;
  padding-top: 2px;
  box-sizing: border-box;
}
/* Grid lines */
.gcal-grid-lines {
  position: absolute;
  left: 56px;
  right: 0;
  top: 0;
  bottom: 0;
  display: flex;
  flex-direction: column;
  pointer-events: none;
  z-index: 1;
}
.gcal-grid-line {
  height: 48px;
  border-top: 1px solid var(--line);
}
/* Day columns */
.gcal-day-col {
  flex: 1;
  position: relative;
  height: calc(13 * 48px); /* 13 hours × 48px each */
  border-left: 1px solid var(--line);
  min-width: 0;
}
.gcal-day-col:first-of-type {
  border-left: 0;
}

/* ── Event blocks (positioned) ────────────────────────────────────────────── */
/*
 * Fix #6: chosen events use a solid green left border to stand out clearly
 *   from the plain grey classes.
 * Fix #7: title wraps up to 2 lines; title attribute shows full text on hover.
 */
.gcal-event-block {
  position: absolute;
  border-radius: 5px;
  padding: 3px 5px 3px 7px;
  font-size: 10px;
  line-height: 1.35;
  overflow: hidden;
  z-index: 2;
  border: 0;
  text-align: left;
  min-height: 22px;
  display: flex;
  flex-direction: column;
  cursor: pointer;
}
/* Fix #7: allow title to wrap up to 2 lines */
.gcal-event-block strong {
  font-size: 10px;
  font-weight: 600;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: normal;
  line-height: 1.3;
}
.gcal-event-block span {
  font-size: 9px;
  opacity: 0.85;
  white-space: nowrap;
}
/* Classes: plain grey */
.gcal-class {
  background: #f0f1ec;
  color: var(--ink);
  border-left: 3px solid #c4c9bf;
}
/* Fix #6: chosen events: stronger green with solid left border */
.gcal-chosen {
  background: #d4eed7;
  color: var(--green-dark);
  border-left: 3px solid var(--green);
}
.gcal-cancelled {
  background: #f8e9e3 !important;
  color: #9c4938 !important;
  border-left: 3px solid #d9847a !important;
}
.gcal-event-block:focus-visible {
  outline: 3px solid #57a77a;
  outline-offset: 2px;
  z-index: 10;
}

/* "Now" line */
.gcal-now-line {
  position: absolute;
  left: 0;
  right: 0;
  height: 2px;
  background: var(--green);
  z-index: 3;
  pointer-events: none;
}
.gcal-now-line::before {
  content: "";
  position: absolute;
  left: -4px;
  top: -4px;
  width: 10px;
  height: 10px;
  background: var(--green);
  border-radius: 50%;
}

/* ── Month view ───────────────────────────────────────────────────────────── */
/*
 * Fix #1: both header and grid use repeat(7, minmax(0,1fr)) so every column
 * is equal width and day numbers always sit under the correct weekday header.
 * Fix #5: chips use white-space:nowrap + overflow:hidden + text-overflow:ellipsis.
 */
.gcal-month {
  padding: 12px;
}
.gcal-month-header {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 2px;
  margin-bottom: 4px;
}
.gcal-month-dow {
  font-size: 10px;
  color: var(--muted);
  text-align: center;
  padding: 4px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.4px;
}
.gcal-month-grid {
  display: grid;
  grid-template-columns: repeat(7, minmax(0, 1fr));
  gap: 2px;
}
.gcal-month-cell {
  min-height: 80px;
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 4px 5px;
  background: white;
  text-align: left;
  display: flex;
  flex-direction: column;
  gap: 2px;
  font-size: 10px;
  cursor: pointer;
  min-width: 0;
  overflow: hidden;
}
.gcal-month-cell:hover {
  background: var(--bg);
}
.gcal-month-cell:focus-visible {
  outline: 3px solid #57a77a;
  outline-offset: 2px;
}
.gcal-other-month {
  background: #fafafa;
  opacity: 0.55;
}
.gcal-today-cell {
  border-color: var(--green);
}
.gcal-demo-week-cell {
  background: #f1f9f2;
}
.gcal-month-day-num {
  font-size: 13px;
  font-weight: 600;
  color: var(--ink);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 26px;
  height: 26px;
  border-radius: 50%;
  flex: none;
  /* Fix #3 (month): today dot wins over demo-week background */
}
/* Fix #3: today dot in month view — more specific than .gcal-demo-week-cell .gcal-month-day-num */
.gcal-today-cell .gcal-today-dot,
.gcal-month-day-num.gcal-today-dot {
  background: var(--green);
  color: white !important;
}
.gcal-demo-week-label {
  font-size: 8px;
  color: var(--green);
  font-weight: 600;
  letter-spacing: 0.3px;
  background: var(--mint);
  border-radius: 3px;
  padding: 1px 4px;
  align-self: flex-start;
  white-space: nowrap;
}
/* Fix #1 + #5: chips are single-line with ellipsis; no content can widen the cell */
.gcal-month-chip {
  display: block;
  background: #d4eed7;
  color: var(--green-dark);
  border-radius: 3px;
  padding: 1px 4px;
  font-size: 9px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  min-width: 0;
}
.gcal-chip-cancelled {
  background: #f8e9e3;
  color: #9c4938;
}
.gcal-month-more {
  font-size: 9px;
  color: var(--muted);
  padding-left: 4px;
}

/* ── Year view ────────────────────────────────────────────────────────────── */
.gcal-year {
  display: grid;
  grid-template-columns: repeat(4, minmax(0, 1fr));
  gap: 20px;
  padding: 16px;
}
.gcal-mini-month {
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.gcal-mini-month-title {
  font-size: 12px;
  font-weight: 700;
  color: var(--ink);
  margin-bottom: 4px;
}
.gcal-mini-header {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
  margin-bottom: 2px;
}
.gcal-mini-dow {
  font-size: 8px;
  color: var(--muted);
  text-align: center;
  font-weight: 600;
}
.gcal-mini-grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 1px;
}
.gcal-mini-cell {
  position: relative;
  font-size: 9px;
  text-align: center;
  padding: 2px 0;
  border-radius: 3px;
  background: none;
  border: 0;
  color: var(--ink);
  cursor: pointer;
  line-height: 1.5;
}
.gcal-mini-cell:hover {
  background: var(--mint);
}
