      }

      demo.update((s) => ({
        ...s,
        constraints: previous ?? (isFollowUp ? s.constraints : {}),
        messages: [...s.messages, { role: "user", text }],
      }));
      await run((snapshot) =>
        requestPlan(
          resolvedText,
          context ?? (isFollowUp ? snapshot.constraints : {}),
          snapshot,
          fetcher,
          isWatsonxMode(),
        ),
      );
    },
  };
