  margin-top: 8px;
  font-size: 12px;
  line-height: 1.45;
}
.agenda-entry strong {
  font-weight: 600;
}
.agenda-entry span,
.agenda-entry small {
  font-size: 11px;
}
.agenda-entry.commitment {
  background: var(--bg);
  color: var(--muted);
}
.agenda-entry.chosen {
  background: var(--mint);
  color: var(--green-dark);
  cursor: pointer;
}
.agenda-entry.cancelled {
  background: #fff0e8;
  color: #97412e;
}
