}
.section-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 17px;
}
.panel {
  background: white;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 22px;
}
.week {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 9px;
}
.day-head {
  font-size: 11px;
  color: var(--muted);
  padding: 2px 0 11px;
  display: flex;
  gap: 7px;
  align-items: center;
}
.day-head strong {
  font-size: 17px;
  color: var(--ink);
  font-weight: 600;
}
.day-head.today strong {
  background: var(--green);
  color: white;
  border-radius: 999px;
  min-width: 29px;
  height: 29px;
  padding: 0 10px;
  display: grid;
  place-items: center;
  white-space: nowrap;
}
.week-day {
  min-width: 0;
}
.calendar-item {
  padding: 10px 9px;
  border-radius: 7px;
  background: #f2f3ef;
  margin-bottom: 7px;
  font-size: 10px;
  min-height: 53px;
  line-height: 1.45;
  border: 0;
  display: block;
  width: 100%;
  text-align: left;
}
.calendar-item strong {
  display: block;
  font-size: 10px;
  font-weight: 600;
  margin-bottom: 4px;
}
.calendar-item span {
  color: var(--muted);
  font-size: 9px;
}
.calendar-item.event {
  background: #e7f1e6;
  color: var(--green);
}
.calendar-item.cancelled {
  background: #f8e9e3;
  color: #9c4938;
}
.add-day {
  width: 100%;
  border: 1px dashed #d5ded3;
  background: none;
  color: #82917f;
  font-size: 11px;
  height: 31px;
  border-radius: 6px;
}
.add-day:hover {
  background: var(--mint);
}
.legend {
  display: flex;
  align-items: center;
  gap: 16px;
  color: var(--muted);
  font-size: 10px;
  margin-top: 13px;
}
.dot {
  display: inline-block;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #a8b4a8;
  margin-right: 5px;
}
.dot.green {
  background: #5e9c6b;
}
.filters {
  display: flex;
  gap: 7px;
  flex-wrap: wrap;
  margin-top: 12px;
  margin-bottom: 20px;
}
.chip {
  border: 1px solid var(--line);
  border-radius: 7px;
  background: white;
  padding: 7px 12px;
  color: var(--muted);
  font-size: 11px;
}
.chip.active {
  background: var(--green);
  color: white;
  border-color: var(--green);
}
.chip:hover {
  border-color: var(--green);
}
.event-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 15px;
}
.event-card {
  background: white;
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  min-width: 0;
}
.poster {
  height: 118px;
  padding: 18px;
  position: relative;
  overflow: hidden;
  color: #344e40;
  background: #e9eee0;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.poster.career {
  background: #ece6f3;
  color: #624d76;
}
.poster.social {
  background: #f4e7ce;
  color: #7b6133;
}
.poster.arts {
  background: #e8e8f0;
  color: #5c6183;
}
.poster.wellbeing {
  background: #e1eeec;
  color: #3f7166;
}
.poster::after {
  content: "";
  width: 120px;
  height: 120px;
  border: 1px solid currentColor;
  opacity: 0.22;
  position: absolute;
  border-radius: 50%;
  right: -30px;
  bottom: -40px;
}
.poster small {
  font-size: 8px;
  letter-spacing: 1.3px;
}
.poster b {
  font-size: 20px;
  font-weight: 550;
  letter-spacing: -0.4px;
  line-height: 1.1;
  max-width: 120px;
}
.poster .icon-btn {
  position: absolute;
  right: 12px;
  top: 12px;
  background: #ffffffc9;
  border: 0;
  z-index: 1;
  width: 28px;
  height: 28px;
}
.poster .icon-btn .icon {
  width: 15px;
  height: 15px;
}
.event-body {
  padding: 15px;
  display: flex;
  flex-direction: column;
  flex: 1;
}
.tag {
  font-size: 9px;
  text-transform: uppercase;
  letter-spacing: 0.7px;
  color: #527654;
  font-weight: 700;
  display: inline-block;
  margin-bottom: 8px;
}
.tag.career {
  color: #795c94;
}
.tag.social {
  color: #936b36;
}
.event-title {
  background: none;
  border: 0;
  text-align: left;
  padding: 0;
  margin-bottom: 11px;
}
.event-title:hover {
  color: var(--green);
}
.event-title h3 {
  font-size: 13px;
  min-height: 35px;
}
.meta {
  color: var(--muted);
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-size: 10px;
  margin: 5px 0;
  line-height: 1.5;
}
.meta .icon {
  width: 13px;
  height: 13px;
  margin-top: 1px;
}
.reason {
  font-size: 10px;
  line-height: 1.6;
  color: #527357;
  padding-top: 10px;
  margin-top: auto;
  margin-bottom: 11px;
}
.reason.blocked {
  color: var(--notice-ink);
}
.event-body .btn.blocked {
  background: var(--notice-bg);
  border-color: #ead9b4;
  color: var(--notice-ink);
}
.event-body .btn.blocked:hover {
  background: #f3e6c9;
}
.event-body .btn {
  width: 100%;
  font-size: 10px;
  padding: 7px;
  min-height: 32px;
}
.rail .panel {
  padding: 20px;
}
.rail h2 {
  font-size: 14px;
}
.planner-teaser {
  text-align: center;
  background: #fff;
}
.mascot {
  width: 125px;
  height: 120px;
  object-fit: contain;
  display: block;
  margin: 0 auto 12px;
}
.planner-teaser h2 {
  font-size: 19px;
}
.planner-teaser p {
  font-size: 11px;
  color: var(--muted);
  margin: 9px 0 16px;
}
.planner-teaser .btn {
  width: 100%;
}
.label {
  font-size: 9px;
  letter-spacing: 0.5px;
  color: var(--muted);
  display: inline-block;
  margin-top: 12px;
}
.feed {
  border-bottom: 1px solid var(--line);
  padding: 13px 0;
}
.feed:last-child {
  border-bottom: 0;
  padding-bottom: 0;
}
.feed strong {
  font-size: 11px;
  font-weight: 600;
  line-height: 1.5;
}
.feed p {
  font-size: 10px;
  color: var(--muted);
  margin: 4px 0 0;
}
.feed .text-btn {
  font-size: 10px;
  margin-top: 6px;
  padding-left: 0;
}
.group {
  display: flex;
  gap: 10px;
  align-items: center;
  padding: 10px 0;
}
.group-icon {
  width: 32px;
  height: 32px;
  border-radius: 9px;
  display: grid;
  place-items: center;
  background: #eff1e7;
  color: #6c7b52;
}
.group strong {
  font-size: 11px;
}
.group small {
  display: block;
  font-size: 9px;
  color: var(--muted);
  margin-top: 3px;
}
.section-footer {
  font-size: 10px;
  color: var(--muted);
  margin-top: 25px;
  display: flex;
  justify-content: space-between;
  gap: 12px;
}
.planner-layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) 320px;
  gap: 22px;
}
.chat-panel {
  display: flex;
  flex-direction: column;
  min-height: 620px;
}
.chat-header {
  display: flex;
  gap: 12px;
  align-items: center;
  padding-bottom: 17px;
  border-bottom: 1px solid var(--line);
}
.chat-header img {
  width: 45px;
  height: 45px;
  object-fit: contain;
}
.chat-header h2 {
  font-size: 15px;
}
.status-label {
  font-size: 10px;
  color: var(--muted);
  margin-top: 4px;
  display: block;
}
.messages {
  flex: 1;
  min-height: 310px;
  max-height: 570px;
  overflow: auto;
  padding: 20px 0;
  display: flex;
  flex-direction: column;
  gap: 18px;
}
.message {
  display: flex;
  gap: 10px;
  align-items: flex-start;
}
.message img {
  width: 30px;
  height: 32px;
  object-fit: contain;
}
.bubble {
  background: var(--bg);
  border-radius: 0 12px 12px 12px;
  padding: 14px 16px;
  font-size: 12px;
  line-height: 1.7;
  max-width: 90%;
  white-space: pre-line;
}
.message.user-msg {
  justify-content: flex-end;
}
.user-msg .bubble {
  background: var(--mint);
  border-radius: 12px 0 12px 12px;
  color: var(--green-dark);
}
.prompts {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
  margin-bottom: 15px;
}
.prompts button {
  font-size: 10px;
  background: white;
  border: 1px solid var(--line);
  border-radius: 7px;
  padding: 8px 10px;
  text-align: left;
}
.prompts button:hover {
  border-color: var(--green);
  background: var(--mint);
}
.active-filters {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 6px;
  margin-bottom: 10px;
  padding: 8px 10px;
  background: var(--mint);
  border-radius: 8px;
  border: 1px solid #bacdbc;
}
.active-filters-label {
  font-size: 10px;
  color: var(--muted);
  font-weight: 600;
  white-space: nowrap;
}
.filter-chip {
  font-size: 10px;
  background: white;
  border: 1px solid var(--green);
  border-radius: 12px;
  padding: 4px 10px;
  color: var(--green);
  cursor: pointer;
  font-weight: 500;
  transition: background 0.1s;
}
.filter-chip:hover:not(:disabled) {
  background: var(--green);
  color: white;
}
.filter-chip:disabled {
  opacity: 0.55;
  cursor: default;
}
.filter-chip-clear {
  border-color: var(--muted);
  color: var(--muted);
  margin-left: auto;
}
.filter-chip-clear:hover:not(:disabled) {
  background: var(--muted);
  color: white;
}
.example-prompts {
  display: flex;
  flex-direction: column;
  gap: 6px;
  margin-top: 10px;
}
.example-prompt-btn {
  font-size: 11px;
  background: var(--mint);
  border: 1px solid var(--green);
  border-radius: 8px;
  padding: 8px 12px;
  text-align: left;
  color: var(--green);
  cursor: pointer;
  font-weight: 500;
}
.example-prompt-btn:hover:not(:disabled) {
  background: var(--green);
  color: white;
}
.example-prompt-btn:disabled {
  opacity: 0.55;
  cursor: default;
}
.overlap-label {
  font-size: 10px;
  font-weight: 600;
  color: var(--muted);
  margin: 12px 0 6px;
  text-transform: uppercase;
  letter-spacing: 0.04em;
}
.composer {
  display: flex;
  align-items: flex-end;
  gap: 10px;
  border: 1px solid #bacdbc;
  border-radius: 10px;
  padding: 9px 10px;
  background: white;
}
.composer textarea {
  border: 0;
  resize: none;
  flex: 1;
  min-width: 0;
  padding: 5px;
  font-size: 12px;
  line-height: 1.5;
  outline: none;
  height: 46px;
  max-height: 130px;
}
.composer button {
  background: var(--green);
  color: white;
  border: 0;
  border-radius: 7px;
  width: 36px;
  height: 36px;
  display: grid;
  place-items: center;
}
.fineprint {
  font-size: 9px;
  line-height: 1.5;
  color: var(--muted);
  margin: 9px 0 0;
  text-align: center;
}
.draft-item {
  padding: 15px 0;
  border-bottom: 1px solid var(--line);
}
.draft-item:last-child {
  border: 0;
}
.draft-item h3 {
  font-size: 12px;
}
.draft-item .meta {
  font-size: 10px;
}
.draft-item .reason {
  margin-bottom: 8px;
}
.draft-item .btn {
  width: 100%;
}
.empty {
  text-align: center;
  padding: 40px 20px;
  color: var(--muted);
  font-size: 12px;
  line-height: 1.7;
}
.empty .icon {
  display: block;
  margin: 0 auto 15px;
  width: 30px;
  height: 30px;
  color: #9fb39e;
}
.empty h3 {
  color: var(--ink);
  margin-bottom: 8px;
}
.summary-line {
  display: flex;
  justify-content: space-between;
  padding: 10px 0;
  font-size: 11px;
  border-bottom: 1px solid var(--line);
}
.summary-line:last-child {
  border: 0;
}
.notice {
  border-radius: 9px;
  background: var(--notice-bg);
  color: var(--notice-ink);
  padding: 13px 15px;
  font-size: 11px;
  line-height: 1.6;
  margin-bottom: 18px;
}
.notice .btn {
  margin-top: 9px;
}
.calendar-full .week {
  gap: 13px;
}
.calendar-full .calendar-item {
  font-size: 12px;
  min-height: 90px;
  padding: 15px;
}
.calendar-full .calendar-item strong {
  font-size: 12px;
}
.calendar-full .calendar-item span {
  font-size: 11px;
}
.calendar-full .week-day {
  min-height: 330px;
}
.calendar-full .day-head {
  padding-bottom: 20px;
}
.form-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 18px;
}
.field {
  display: flex;
  flex-direction: column;
  gap: 7px;
  font-size: 12px;
  color: var(--muted);
}
.field input,
.field select,
.field textarea {
  border: 1px solid var(--line);
  border-radius: 7px;
  background: white;
  padding: 11px;
  color: var(--ink);
  width: 100%;
}
.field textarea {
  min-height: 90px;
}
.field.full {
  grid-column: 1/-1;
}
.row {
  display: flex;
  gap: 10px;
  align-items: center;
  flex-wrap: wrap;
}
.block-row {
  display: flex;
  justify-content: space-between;
  gap: 20px;
  align-items: center;
  padding: 13px 0;
  border-bottom: 1px solid var(--line);
  font-size: 12px;
}
.block-row small {
  display: block;
  color: var(--muted);
  margin-top: 5px;
}
.wide-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.4fr) minmax(0, 1fr);
  gap: 24px;
}
.topic-options {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
  margin: 16px 0;
}
.topic-options label {
  font-size: 12px;
  background: var(--bg);
  padding: 10px;
  border-radius: 7px;
}
.topic-options input {
  accent-color: var(--green);
  margin-right: 7px;
}
.discussion {
  padding: 20px 0;
  border-bottom: 1px solid var(--line);
  display: flex;
  gap: 15px;
}
.discussion p {
  font-size: 12px;
  margin: 8px 0;
  color: var(--muted);
}
.discussion .avatar {
  flex: none;
}
.discussion small {
  color: var(--muted);
  font-size: 10px;
}
.discussion button {
  margin-top: 8px;
}
.settings-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 20px;
  padding: 22px 0;
  border-bottom: 1px solid var(--line);
}
.settings-row p {
  margin: 5px 0 0;
  font-size: 12px;
  color: var(--muted);
}
.settings-row input {
  accent-color: var(--green);
  width: 18px;
  height: 18px;
}
.settings-row:last-child {
  border: 0;
}
.mobile-menu {
  display: none;
}
/* ── Event detail full-page overlay ─────────────────────────────────────── */
.event-detail-overlay {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
}
.event-detail-backdrop {
  position: fixed;
  inset: 0;
  background: #15291f60;
  z-index: 199;
}
.event-detail-bar {
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  height: 56px;
  background: white;
  border-bottom: 1px solid var(--line);
  display: flex;
  align-items: center;
  justify-content: flex-end;
  padding: 0 24px;
  z-index: 201;
  box-shadow: 0 2px 8px #183e3108;
}
.event-detail-close {
  width: 36px;
  height: 36px;
  border: 1px solid var(--line);
  border-radius: 8px;
  background: white;
  display: flex;
  align-items: center;
  justify-content: center;
}
.event-detail-close:hover {
  background: var(--bg);
}
.event-detail-scroll {
  position: fixed;
  inset: 56px 0 0 0;
  overflow-y: auto;
  z-index: 200;
  background: var(--bg);
}
.event-detail-hero {
  height: 220px;
  display: flex;
  align-items: flex-end;
  border-radius: 0;
  overflow: hidden;
}
.event-detail-hero::after {
  display: none;
}
.event-detail-hero-inner {
  max-width: 900px;
  margin: 0 auto;
  width: 100%;
  padding: 28px 32px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.event-detail-hero-title {
  font-size: 32px;
  font-weight: 900;
  letter-spacing: -0.5px;
  line-height: 1.15;
  margin: 0;
  color: inherit;
}
.event-detail-body {
  max-width: 900px;
  margin: 0 auto;
  padding: 32px 32px 60px;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 300px;
  gap: 32px;
  align-items: start;
}
.event-detail-main {
  display: flex;
  flex-direction: column;
  gap: 24px;
}
.event-detail-desc {
  font-size: 16px;
  line-height: 1.7;
  color: var(--ink);
  margin: 0;
}
.event-detail-info-grid {
  display: flex;
  flex-direction: column;
  gap: 14px;
  background: white;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 20px 22px;
}
.event-detail-info-row {
  display: flex;
  align-items: flex-start;
  gap: 12px;
  font-size: 14px;
  color: var(--ink);
  line-height: 1.5;
}
.event-detail-info-row .icon {
  flex: none;
  margin-top: 1px;
  color: var(--muted);
}
.event-detail-reasons {
  background: var(--mint);
  border-radius: 10px;
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.event-detail-reason-item {
  font-size: 13px;
  color: var(--green-dark);
  font-weight: 600;
}
.event-detail-section {
  display: flex;
  flex-direction: column;
  gap: 8px;
}
.event-detail-section-title {
  font-size: 16px;
  font-weight: 800;
  margin: 0;
}
.event-detail-communities {
  display: flex;
  flex-direction: column;
  gap: 6px;
}
.event-detail-community-link {
  font-size: 14px;
  font-weight: 600;
  color: var(--green);
  text-decoration: underline;
  text-underline-offset: 3px;
}
.event-detail-evidence {
  background: white;
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 18px 22px;
  font-size: 13px;
}
.event-detail-evidence summary {
  font-weight: 700;
  cursor: pointer;
  list-style: none;
  display: flex;
  align-items: center;
  gap: 8px;
}
.event-detail-evidence summary::before {
  content: "▶";
  font-size: 10px;
  color: var(--muted);
  transition: transform 0.15s;
}
.event-detail-evidence[open] summary::before {
  transform: rotate(90deg);
}
.event-detail-aside {
  position: sticky;
  top: calc(var(--topbar-h) + 24px);
}
.event-detail-aside-inner {
  background: white;
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
}
.event-detail-aside-banner {
  height: 110px;
  display: flex;
  align-items: flex-end;
  padding: 14px 18px;
  border-radius: 0;
}
.event-detail-aside-banner::after {
  display: none;
}
.event-detail-aside-body {
  padding: 18px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}
.event-detail-aside-date {
  font-size: 13px;
  font-weight: 700;
  color: var(--ink);
  margin: 0;
}
.event-detail-aside-loc {
  font-size: 12px;
  color: var(--muted);
  margin: 0;
  display: flex;
  align-items: center;
  gap: 6px;
}
@media (max-width: 700px) {
  .event-detail-body {
    grid-template-columns: minmax(0, 1fr);
    padding: 20px 16px 48px;
  }
  .event-detail-aside {
    position: static;
  }
  .event-detail-hero-title {
    font-size: 24px;
  }
}
#toast {
  position: fixed;
  bottom: 25px;
  left: calc(50% + 100px);
  transform: translateX(-50%) translateY(20px);
  opacity: 0;
  pointer-events: none;
  z-index: 100;
  background: var(--green-dark);
  color: white;
  border-radius: 9px;
  padding: 13px 22px;
  box-shadow: var(--shadow);
  font-size: 12px;
  transition:
    opacity 0.2s,
    transform 0.2s;
  max-width: calc(100% - 32px);
}
#toast.show {
  opacity: 1;
  transform: translateX(-50%) translateY(0);
  pointer-events: auto;
}
#toast {
  display: flex;
  align-items: center;
  gap: 16px;
}
.toast-actions {
  display: flex;
  gap: 4px;
  flex: none;
}
.toast-actions button {
  background: transparent;
  border: 0;
  color: var(--mint);
  font: inherit;
  font-weight: 700;
  padding: 6px 8px;
  border-radius: 6px;
  cursor: pointer;
  text-decoration: underline;
  text-underline-offset: 3px;
}
.toast-actions button:hover {
  background: #ffffff1f;
}
.toast-actions button:focus-visible {
  outline: 2px solid var(--mint);
  outline-offset: 1px;
}
.page-enter {
  animation: reveal 0.3s cubic-bezier(0.16, 1, 0.3, 1);
}
@keyframes reveal {
  from {
    opacity: 0.6;
    transform: translateY(5px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}
