    #[test]
    fn free_food_does_not_set_free_admission() {
        let r = parse("free food");
        assert_eq!(r.constraints.food.as_deref(), Some("Free meal"));
        assert_eq!(r.constraints.free, None, "'free food' must not set free admission");
    }

