            if matches(
                &format!(r"(?:no|not|avoid|without)\s+(?:any\s+)?(?:{words})"),
                &q,
            ) {
                excluded.push(topic.to_string());
            }
        }
        if !topics.is_empty() {
            c.topics = Some(
                topics
                    .into_iter()
                    .filter(|t| !excluded.contains(t))
                    .collect(),
            );
        }
        if !excluded.is_empty() {
            c.excluded = Some(excluded);
        }
