            c.days = Some(vec![5, 6]);
        }
        if matches(r"\bweekday", &q) {
            c.days = Some(vec![0, 1, 2, 3, 4]);
        }
        if matches(r"\bafternoon", &q) {
            c.after = Some(720);
            c.before = Some(1020);
