    assert.deepEqual(
      interpretRequest("practice some English").constraints.topics,
      ["Social"],
    );
  });

  it("'make some friends' → Social", () => {
    assert.deepEqual(interpretRequest("make some friends").constraints.topics, ["Social"]);
  });

  it("'make new friends' → Social", () => {
