  });

  it("'meet new people' → Social", () => {
    assert.deepEqual(interpretRequest("meet new people").constraints.topics, ["Social"]);
  });

  it("'get a job' → Career", () => {
    assert.deepEqual(interpretRequest("get a job").constraints.topics, ["Career"]);
  });

  it("'language exchange' → Social", () => {
